    fn write_log(session: &Session, entries: &[LogEntry]) {
        let path = session.root().join("events.jsonl");
        let mut writer = LogWriter::open(&path).expect("open log");
        for entry in entries {
            writer.write_entry(entry).expect("write entry");
        }
    }

