pub use hanihi_core::agent::{TurnSummary, connect_chat_model};

use crate::ui::{print_coloured, println_coloured};

const DEFAULT_WORKING_DIR: &str = "./working";
/// Default cap on model turns per request. Effectively unlimited: a sane
/// upper bound so runaway tool-call loops still terminate, but far above any
/// realistic working session.
const DEFAULT_MAX_TURNS: usize = 1000;
/// Default cap on model turns in task mode (long-horizon self-improvement).
const TASK_MAX_TURNS: usize = 1000;

#[derive(Parser, Debug)]
#[command(
    name = "hānihi",
    version,
    about = "Rust agent harness: rig + rmcp + reedline"
)]
struct Args {
    /// OpenAI-compatible chat completions base URL.
    #[arg(
        long,
        env = "LLM_BASE_URL",
        default_value = "https://api.deepseek.com/v1"
    )]
    base_url: String,

    /// API key (or set LLM_API_KEY).
    #[arg(long, env = "LLM_API_KEY")]
    api_key: Option<String>,

    /// Model name (or set LLM_MODEL).
    #[arg(long, env = "LLM_MODEL", default_value = "deepseek-chat")]
    model: String,

    /// Working directory for sessions (default: ./working, relative to cwd).
    #[arg(long, env = "HANIHI_WORKING_DIR", default_value = DEFAULT_WORKING_DIR)]
    working_dir: PathBuf,

    /// Use an existing session by name (default: "default-session").
    #[arg(long, default_value = "default-session")]
    session: String,

    /// Create a new session with this name and use it.
    #[arg(long, conflicts_with = "session")]
    new_session: Option<String>,

    /// MCP stdio server command(s) to attach, e.g.
    /// `--mcp-command "./target/debug/mcp-echo-server"`. May be repeated.
    #[arg(long = "mcp-command", value_name = "CMD")]
    mcp_commands: Vec<String>,

    /// Run a single turn and exit (no REPL).
    #[arg(long, value_name = "PROMPT")]
    once: Option<String>,

    /// Register write tools (apply_patch, write_file) — enables editing the
    /// enclosing repository. Off by default; analysis and build tools are
    /// always on.
    #[arg(long)]
    write: bool,

    /// Run a single long-horizon turn with the task-mode system prompt
    /// (workflow gates: fmt → test → build → clippy → commit). Takes
    /// precedence over --once.
    #[arg(long, value_name = "PROMPT")]
    task: Option<String>,

    /// Maximum model turns per request (default: 1000; task mode: 1000).
    #[arg(long)]
    max_turns: Option<usize>,

    /// Append this text to the system prompt. Repeatable. When used with an
    /// existing session, the appended text is persisted to the session so it
    /// applies on future resumes too.
    #[arg(long = "prompt", value_name = "TEXT")]
    prompt_append: Vec<String>,

    /// Append the content of this file to the system prompt. Repeatable.
    /// When used with an existing session, the appended content is persisted
    /// to the session so it applies on future resumes too.
    #[arg(long = "prompt-file", value_name = "PATH")]
    prompt_files: Vec<PathBuf>,

    /// Replace the entire system prompt with the additions (no base prompt
    /// is prepended). For use with --session to rewrite the stored prompt,
    /// or with --new-session to override the default. Mutually exclusive
    /// with --prompt/--prompt-file append semantics (see below).
    #[arg(long)]
    new_prompt: bool,
}

/// Extract a short provider name from a base URL hostname.
fn provider_from_url(url: &str) -> &str {
    // Strip scheme.
    let host = url
        .trim_start_matches("https://")
        .trim_start_matches("http://")
        .split('/')
        .next()
        .unwrap_or("unknown");
    // e.g. "api.deepseek.com" -> "deepseek", "api.openai.com" -> "openai"
    host.trim_start_matches("api.")
        .trim_start_matches("api-")
        .split('.')
        .next()
        .unwrap_or("unknown")
}

/// Read the given prompt files and return their concatenated contents.
fn read_prompt_files(paths: &[PathBuf]) -> Result<String, AgentError> {
    let mut out = String::new();
    for path in paths {
        let content = fs::read_to_string(path)?;
        if !out.is_empty() {
            out.push('\n');
        }
        out.push_str(&content);
    }
    Ok(out)
}

/// Read a single file's contents for use as a prompt, resolved against the
/// given base directory when the path is not absolute.
fn read_prompt_file(base: &Path, path: &str) -> Result<String, AgentError> {
    let resolved = if Path::new(path).is_absolute() {
        PathBuf::from(path)
    } else {
        base.join(path)
    };
    if !resolved.is_file() {
        return Err(AgentError::Io(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("no such file: {}", resolved.display()),
        )));
    }
    fs::read_to_string(&resolved).map_err(AgentError::Io)
}

/// Concatenate the explicit additions (`--prompt` strings and the contents
/// of `--prompt-file` files) into one block.
fn collect_extras(
    prompt_appends: &[String],
    prompt_files: &[PathBuf],
) -> Result<String, AgentError> {
    let file_text = read_prompt_files(prompt_files)?;
    let mut parts: Vec<String> = Vec::new();
    parts.extend(prompt_appends.iter().cloned());
    if !file_text.is_empty() {
        parts.push(file_text);
    }
    Ok(parts.join("\n\n"))
}

/// Whether any explicit prompt additions were supplied.
fn has_extras(prompt_appends: &[String], prompt_files: &[PathBuf]) -> bool {
    !prompt_appends.is_empty() || !prompt_files.is_empty()
}

/// Read the system prompt stored in an existing session's session.json.
fn stored_session_prompt(working_dir: &std::path::Path, session_name: &str) -> Option<String> {
    let meta_path = working_dir
        .join("sessions")
        .join(session_name)
        .join("session.json");
    let bytes = fs::read_to_string(meta_path).ok()?;
    let meta: serde_json::Value = serde_json::from_str(&bytes).ok()?;
    meta.get("system_prompt")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

/// Persist a system prompt into an existing session's session.json. Reads
/// the file, updates the field, writes it back.
fn write_session_prompt(
    working_dir: &std::path::Path,
    session_name: &str,
    prompt: &str,
) -> Result<(), AgentError> {
    let meta_path = working_dir
        .join("sessions")
        .join(session_name)
        .join("session.json");
    let bytes = fs::read(&meta_path).map_err(AgentError::Io)?;
    let mut meta: serde_json::Value = serde_json::from_slice(&bytes).map_err(AgentError::Json)?;
    meta["system_prompt"] = serde_json::Value::String(prompt.to_string());
    fs::write(&meta_path, serde_json::to_string_pretty(&meta)?).map_err(AgentError::Io)?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), AgentError> {
    tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .init();

    let args = Args::parse();
    let api_key = args
        .api_key
        .filter(|k| !k.is_empty())
        .ok_or(AgentError::MissingApiKey)?;

    // Resolve working directory relative to cwd.
    let working_dir = if args.working_dir.is_absolute() {
        args.working_dir.clone()
    } else {
        std::env::current_dir()?.join(&args.working_dir)
    };

    let mut mgr = SessionManager::new(&working_dir);
    let provider = provider_from_url(&args.base_url);

    let task_mode = args.task.is_some();
    let base_prompt: &str = if task_mode {
        hanihi_core::agent::TASK_SYSTEM_PROMPT
    } else {
        hanihi_core::agent::DEFAULT_SYSTEM_PROMPT
    };

    // Determine session name and whether to auto-create.
    let (session_name, is_new) = if let Some(ref name) = args.new_session {
        (name.clone(), true)
    } else {
        let name = args.session.clone();
        // Auto-create default-session if it doesn't exist.
        let is_new = name == "default-session" && !mgr.exists(&name);
        (name, is_new)
    };

    let had_extras = has_extras(&args.prompt_append, &args.prompt_files);

    // Resolve the system prompt this invocation will use, and whether it
    // must be persisted back to the session's metadata.
    //
    // Prompt resolution rules:
    //  - `--new-prompt` on any session: the additions (collected from
    //    --prompt / --prompt-file) become the ENTIRE prompt. On an existing
    //    session this replaces and persists the stored prompt.
    //  - Otherwise `--prompt` / `--prompt-file` append to the base prompt
    //    (new session) or to the stored prompt (existing session), and the
    //    appended result is persisted so it survives a resume.
    //  - With no additions at all, the existing stored prompt is used
    //    unchanged (or the base prompt for a fresh session).
    let (session_prompt, do_persist) = if args.new_prompt {
        // Replace/set the entire prompt from the additions only.
        let prompt = collect_extras(&args.prompt_append, &args.prompt_files)?;
        let effective = if prompt.trim().is_empty() {
            // --new-prompt with nothing supplied: use base as the new prompt.
            base_prompt.to_string()
        } else {
            prompt
        };
        if is_new {
            (effective, false) // creation persists it
        } else {
            (effective, true) // replace + persist the stored prompt
        }
    } else if is_new {
        // Fresh session: base + any appends. persisted by creation.
        let prompt = if had_extras {
            let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
            format!("{base_prompt}\n\n{extras}")
        } else {
            base_prompt.to_string()
        };
        (prompt, false)
    } else if had_extras {
        // Existing session with appends: stored + extras, persisted.
        let stored = stored_session_prompt(&working_dir, &session_name)
            .unwrap_or_else(|| base_prompt.to_string());
        let extras = collect_extras(&args.prompt_append, &args.prompt_files)?;
        let prompt = format!("{stored}\n\n{extras}");
        (prompt, true)
    } else {
        // Existing session, no additions: use stored prompt unchanged.
        let stored = stored_session_prompt(&working_dir, &session_name)
            .unwrap_or_else(|| base_prompt.to_string());
        (stored, false)
    };

    // Create or open the session.
    if is_new {
        if session_name == "default-session" {
            mgr.create_default(&args.model, &session_prompt)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("auto-created session 'default-session'");
        } else {
            mgr.create(&session_name, &args.model, &session_prompt)
                .map_err(|e| AgentError::Rig(e.to_string()))?;
            println!("created session '{session_name}'");
        }
    } else {
        mgr.open(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        if do_persist {
            write_session_prompt(&working_dir, &session_name, &session_prompt)?;
            if args.new_prompt {
                println!("session '{session_name}' system prompt replaced");
            } else {
                println!("session '{session_name}' system prompt extended");
            }
        }
    }

    // Build the agent with the resolved system prompt.
    let mut agent = connect_chat_model_with_prompt(
        args.base_url.clone(),
        api_key.clone(),
        args.model.clone(),
        &session_prompt,
    )?;
    agent.set_max_turns(args.max_turns.unwrap_or(if task_mode {
        TASK_MAX_TURNS
    } else {
        DEFAULT_MAX_TURNS
    }));
    agent.add_tool(builtin_get_time());
    agent.add_tool(builtin_echo());

    // Source-tree tools: read/list/grep/run-command over the enclosing git
    // repository, plus a window into this session's own event log. Ignore
    // rules (.gitignore, .ignore) filter what the agent can see. Write tools
    // (apply_patch, write_file) are registered only with --write.
    match SourceTree::open() {
        Ok(tree) => {
            let tree = Arc::new(tree);
            let traces_dir = working_dir.join("traces").join(&session_name);
            let log_path = working_dir
                .join("sessions")
                .join(&session_name)
                .join("events.jsonl");
            agent.add_tool(builtin_read_file(tree.clone()));
            agent.add_tool(builtin_list_dir(tree.clone()));
            agent.add_tool(builtin_grep(tree.clone()));
            agent.add_tool(builtin_run_command(tree.clone(), traces_dir));
            agent.add_tool(builtin_read_session_log(log_path));
            if args.write {
                agent.add_tool(builtin_apply_patch(tree.clone()));
                agent.add_tool(builtin_write_file(tree));
            }
        }
        Err(e) => println!("source tools disabled (no git repository): {e}"),
    }

    for command in &args.mcp_commands {
        let parts: Vec<String> = command.split_whitespace().map(String::from).collect();
        let (program, rest) = parts.split_first().ok_or_else(|| AgentError::Tool {
            name: "<mcp>".into(),
            message: "empty --mcp-command".into(),
        })?;
        let client = McpClient::connect_stdio(program, rest).await?;
        let tools = client.tool_defs().await?;
        let count = tools.len();
        for tool in tools {
            agent.add_tool(tool);
        }
        println!("attached MCP server '{program}': {count} tool(s)");
    }

    // Get a mutable reference to the open session so we can read its turn
    // count for the "session renewed" metadata below.
    let session = mgr
        .open(&session_name)
        .map_err(|_e| AgentError::Rig("failed to re-open session".into()))?;

    // Replay prior turns from the event log so the agent remembers
    // previous conversations in this session.
    let mut prior_turns = None;
    match session.replay_history() {
        Ok(history) if !history.is_empty() => {
            let msg_count = history.len();
            agent.set_history(history);
            println!("replayed {msg_count} messages from prior session");
        }
        Ok(_) => {} // empty history, nothing to replay
        Err(e) => {
            tracing::warn!("failed to replay session history: {e}");
        }
    }
    // How many turns has this session accumulated so far (including from
    // prior sessions)? Use the session's own counter; it is monotonically
    // increasing across restarts of the same session name.
    if let Ok(turns) = session.total_turns() {
        prior_turns = Some(turns);
    }

    println!(
        "agent ready: model={} tools={} session='{session_name}' max_turns={}{}",
        args.model,
        agent.tool_count(),
        agent.max_turns(),
        if args.write {
            " (write tools enabled)"
        } else {
            ""
        },
    );
    if let Some(t) = prior_turns {
        println!(
            "session '{}' renewed: total turns so far = {t}",
            session_name
        );
    }
    println!("system prompt: {} bytes", session_prompt.len());

    let prompt = args.task.clone().or_else(|| args.once.clone());
    if let Some(prompt) = prompt {
        let mut rx = session
            .run_streaming(&mut agent, provider, &args.model, &prompt)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        while let Some(event) = rx.recv().await {
            match event {
                StreamEvent::TextDelta { text } => print_coloured!("{text}"),
                StreamEvent::ToolCallStart { name, .. } => print_coloured!("\n[🔧 {name}"),
                StreamEvent::ToolCallArgs { .. } => {}
                StreamEvent::ToolCallReady { .. } => {}
                StreamEvent::ToolResult { .. } => println_coloured!(" ✅]"),
                StreamEvent::CompletionRequest { .. } | StreamEvent::CompletionResponse { .. } => {}
                StreamEvent::TurnComplete { summary } => {
                    println!();
                    println_coloured!(
                        "[turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
                        session.turn,
                        summary.tool_calls,
                        summary.usage.input_tokens,
                        summary.usage.output_tokens,
                        agent.max_turns()
                    );
                    agent.set_history(summary.final_history);
                    break;
                }
                StreamEvent::Error { message } => {
                    eprintln!();
                    eprintln!("error: {message}");
                    break;
                }
            }
        }
        mgr.close(&session_name)
            .map_err(|e| AgentError::Rig(e.to_string()))?;
        return Ok(());
    }

    let cwd = std::env::current_dir().map_err(AgentError::Io)?;
    repl(session, agent, provider, &args.model, &cwd, &working_dir).await?;

    mgr.close(&session_name)
        .map_err(|e| AgentError::Rig(e.to_string()))?;
    Ok(())
}

/// Render the per-turn completion footer shown after (and by /session for) a turn.
fn turn_footer(
    model: &str,
    turn: u64,
    tool_calls: usize,
    tokens_in: u64,
    tokens_out: u64,
    max_turns: usize,
) -> String {
    format!(
        "[model: {model} turn {turn} | tool calls: {tool_calls} | tokens: {tokens_in} in / {tokens_out} out | max_turns: {max_turns}]"
    )
}

/// Interactive readline loop.
async fn repl<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    mut agent: Agent<M>,
    provider: &str,
    model_name: &str,
    cwd: &Path,
    working_dir: &Path,
) -> Result<(), AgentError> {
    let history_path = session.root().join("history.txt");
    let history: Box<dyn reedline::History> =
        match FileBackedHistory::with_file(10_000, history_path) {
            Ok(h) => Box::new(h),
            Err(e) => {
                eprintln!("history file disabled: {e}");
                Box::new(FileBackedHistory::new(10_000).expect("in-memory history"))
            }
        };
    let edit_mode = reedline::Emacs::default();
    let mut editor = Reedline::create()
        .with_edit_mode(Box::new(edit_mode))
        .with_history(history)
        .with_highlighter(Box::new(MonoHighlighter::new(Color::Cyan)));
    let prompt = DefaultPrompt::default();
    let mut last_summary: Option<TurnSummary> = None;
    loop {
        match editor.read_line(&prompt) {
            Ok(Signal::Success(line) | Signal::HostCommand(line)) => {
                let line = line.trim().to_string();
                match line.as_str() {
                    "" => continue,
                    "/quit" | "/exit" => break,
                    "/help" => {
                        println!(
                            "commands: /help /tools /clear /session /file /quit — anything else is sent to the model"
                        );
                        continue;
                    }
                    "/tools" => {
                        for def in agent.tool_definitions() {
                            println!("- {}: {}", def.name, def.description);
                        }
                        continue;
                    }
                    "/clear" => {
                        agent.clear_history();
                        println!("history cleared");
                        continue;
                    }
                    "/session" => {
                        println!(
                            "session: '{}' (id={}) turn={} max_turns={}",
                            session.name,
                            session.id,
                            session.turn,
                            agent.max_turns()
                        );
                        if let Some(s) = &last_summary {
                            println!(
                                "{}",
                                turn_footer(
                                    session.model.as_str(),
                                    session.turn,
                                    s.tool_calls,
                                    s.usage.input_tokens,
                                    s.usage.output_tokens,
                                    agent.max_turns(),
                                )
                            );
                        } else {
                            println!("No TurnSummary");
                        }
                        continue;
                    }
                    _ => {}
                }

                // Handle `/file <PATH>`: read the file's contents relative to
                // the working directory (or absolute) and use it as the prompt.
                // Only a single line can be typed at the REPL prompt, so this
                // lets multi-line content (a prompt, a plan, code) be loaded
                // from disk and sent to the model in one go.
                if let Some(rest) = line.strip_prefix("/file ") {
                    let path = rest.trim();
                    if path.is_empty() {
                        eprintln!("/file requires a path");
                        continue;
                    }
                    let content = match read_prompt_file(working_dir, path) {
                        Ok(c) => c,
                        Err(e) => {
                            eprintln!("error reading '{path}': {e}");
                            continue;
                        }
                    };
                    if content.trim().is_empty() {
                        eprintln!("/file '{path}' is empty");
                        continue;
                    }
                    println!(
                        "using contents of '{}' ({}, {} bytes) as prompt",
                        path,
                        cwd.display(),
                        content.len()
                    );
                    last_summary =
                        run_turn(session, &mut agent, provider, model_name, &content).await;
                    continue;
                }

                last_summary = run_turn(session, &mut agent, provider, model_name, &line).await;
            }
            Ok(Signal::CtrlC) | Ok(Signal::ExternalBreak(_)) => continue,
            Ok(Signal::CtrlD) => break,
            Ok(_) => continue,
            Err(e) => {
                eprintln!("readline error: {e}");
                break;
            }
        }
    }

    // Sync history to disk before shutting down.
    if let Err(e) = editor.sync_history() {
        eprintln!("warning: failed to sync history: {e}");
    }
    Ok(())
}

/// Run a single turn with the given prompt and stream the model's output.
async fn run_turn<M: CompletionModel + 'static>(
    session: &mut hanihi_core::session::Session,
    agent: &mut Agent<M>,
    provider: &str,
    model_name: &str,
    prompt: &str,
) -> Option<TurnSummary> {
    match session
        .run_streaming(agent, provider, model_name, prompt)
        .await
    {
        Ok(mut rx) => {
            while let Some(event) = rx.recv().await {
                match event {
                    StreamEvent::TextDelta { text } => print_coloured!("{text}"),
                    StreamEvent::ToolCallStart { name, .. } => print_coloured!("\n[🔧 {name}"),
                    StreamEvent::ToolCallArgs { .. } => {}
                    StreamEvent::ToolCallReady { .. } => {}
                    StreamEvent::ToolResult { .. } => println_coloured!(" ✅]"),
                    StreamEvent::CompletionRequest { .. }
                    | StreamEvent::CompletionResponse { .. } => {}
                    StreamEvent::TurnComplete { summary } => {
                        println!();
                        println_coloured!(
                            "[model: {} turn {} | tool calls: {} | tokens: {} in / {} out | max_turns: {}]",
                            session.model,
                            session.turn,
                            summary.tool_calls,
                            summary.usage.input_tokens,
                            summary.usage.output_tokens,
                            agent.max_turns()
                        );
                        // TODO: Do I need this `clone`?
                        agent.set_history(summary.final_history.clone());
                        return Some(summary);
                    }
                    StreamEvent::Error { message } => {
                        eprintln!();
                        eprintln!("error: {message}");
                        return None;
                    }
                }
            }
            None
        }
        Err(e) => {
            eprintln!("error: {e}");
            None
        }
    }
}

//! Write-path tools: `apply_patch` and `write_file`.
//!
//! These are registered **only** when the CLI is invoked with `--write`.
//! They are scoped to the enclosing git repository via [`SourceTree`]:
//! escapes, git-ignored paths, `.ignore`, and anything under `.git/` are
//! refused. Changes land as local git commits — never pushed. Git is the
//! undo button and the audit trail.

use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::Arc;

use rig::tool::{PortableDynamicTool, ToolExecutionError, ToolOutput};
use serde_json::json;

use crate::debug;
use crate::source::SourceTree;
use crate::tool::{map_source_err, scrubbed_env};

/// Paths the agent may never write, relative to the repo root.
fn is_protected(rel: &str) -> bool {
    rel == ".ignore" || rel == ".gitignore" || rel.starts_with(".git/") || rel == ".git"
}

/// Run `git` with `args` in `root`, with the scrubbed environment, capturing
/// output. Returns `Ok((stdout, stderr))` on success, `Err(message)` on
/// failure (the more informative of stdout/stderr, trimmed).
///
/// Used only for `git add`/`git commit` after a patch is applied; the
/// unreliable `git apply` machinery is deliberately not used.
async fn git_run(root: &Path, args: &[&str]) -> Result<(String, String), String> {
    let mut cmd = tokio::process::Command::new("git");
    cmd.current_dir(root);
    cmd.env_clear();
    for (k, v) in scrubbed_env() {
        cmd.env(k, v);
    }
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::piped());
    cmd.args(args);
    let output = cmd
        .output()
        .await
        .map_err(|e| format!("spawn git {}: {e}", args[0]))?;
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
    let stderr = String::from_utf8_lossy(&output.stderr).into_owned();
    if !output.status.success() {
        let msg = if stderr.trim().is_empty() {
            stdout.trim()
        } else {
            stderr.trim()
        };
        return Err(msg.to_string());
    }
    Ok((stdout, stderr))
}

/// A single body line of a unified-diff hunk.
#[derive(Debug, Clone, PartialEq, Eq)]
enum BodyLine {
    Context(String),
    Del(String),
    Add(String),
}

impl BodyLine {
    fn text(&self) -> &str {
        match self {
            BodyLine::Context(s) | BodyLine::Del(s) | BodyLine::Add(s) => s,
        }
    }

    fn is_del(&self) -> bool {
        matches!(self, BodyLine::Del(_))
    }

    fn is_add(&self) -> bool {
        matches!(self, BodyLine::Add(_))
    }
}

/// One hunk of a file patch. The `@@` counts are parsed but deliberately
/// ignored: line counts are recomputed from the body (the `--recount`
/// behaviour of `git apply`), so hand-composed hunks with slightly off
/// numbers still apply.
#[derive(Debug)]
struct Hunk {
    lines: Vec<BodyLine>,
}

/// A single file touched by a unified diff.
#[derive(Debug)]
struct FilePatch {
    old_path: Option<String>,
    new_path: Option<String>,
    is_new: bool,
    is_delete: bool,
    hunks: Vec<Hunk>,
}

impl FilePatch {
    /// Repo-relative path this patch writes to.
    fn target_rel(&self) -> Result<String, String> {
        match (&self.old_path, &self.new_path) {
            (_, Some(new)) => Ok(new.clone()),
            (Some(old), None) => Ok(old.clone()),
            (None, None) => Err("file patch has neither an old nor a new path".into()),
        }
    }

    /// The same patch with additions and deletions swapped. Applying the
    /// reverse of an already-applied patch succeeds exactly when the change
    /// is present in the working tree.
    #[cfg(test)]
    fn reversed(&self) -> FilePatch {
        FilePatch {
            old_path: self.new_path.clone(),
            new_path: self.old_path.clone(),
            is_new: self.is_delete,
            is_delete: self.is_new,
            hunks: self
                .hunks
                .iter()
                .map(|h| Hunk {
                    lines: h
                        .lines
                        .iter()
                        .map(|l| match l {
                            BodyLine::Context(s) => BodyLine::Context(s.clone()),
                            BodyLine::Del(s) => BodyLine::Add(s.clone()),
                            BodyLine::Add(s) => BodyLine::Del(s.clone()),
                        })
                        .collect(),
                })
                .collect(),
        }
    }
}

/// Result of applying one file patch, before anything is written.
struct AppliedFile {
    abs: PathBuf,
    /// `None` means the file is to be deleted.
    content: Option<String>,
}

fn is_file_marker(a: &str, b: &str) -> bool {
    (a.starts_with("--- /dev/null") || a.starts_with("--- a/")) && b.starts_with("+++ ")
}

/// Split `diff` into per-file blocks. Each block starts at a `--- ` marker
/// line whose following line is `+++ `, and runs to just before the next
/// such pair (or the end of the input).
fn file_blocks(lines: &[&str]) -> Vec<(usize, usize)> {
    let mut blocks = Vec::new();
    let mut i = 0;
    while i + 1 < lines.len() {
        if is_file_marker(lines[i], lines[i + 1]) {
            let start = i;
            let mut j = i + 2;
            while j < lines.len() {
                if j + 1 < lines.len() && is_file_marker(lines[j], lines[j + 1]) {
                    break;
                }
                j += 1;
            }
            blocks.push((start, j));
            i = j;
        } else {
            i += 1;
        }
    }
    blocks
}

/// Parse the path from a `--- ` or `+++ ` marker line. Returns `None` for
/// `/dev/null` (the "file did not exist" side) and strips git's standard
/// `a/`/`b/` prefixes plus any trailing tab metadata.
fn parse_side_path(marker: &str) -> Option<String> {
    let rest = marker.split('\t').next().unwrap_or(marker).trim();
    if rest == "/dev/null" {
        return None;
    }
    let rel = rest
        .strip_prefix("a/")
        .or_else(|| rest.strip_prefix("b/"))
        .unwrap_or(rest);
    Some(rel.to_string())
}

/// Parse a unified diff into per-file patches. Header lines that carry no
/// content (`index`, `new file mode`, `old/new mode`, `similarity index`,
/// ...) are skipped; binary and rename/copy patches are refused.
fn parse_diff(diff: &str) -> Result<Vec<FilePatch>, String> {
    let lines: Vec<&str> = diff.lines().collect();
    let blocks = file_blocks(&lines);
    if blocks.is_empty() {
        debug::log_to_file("apply_patch on non-diff", diff);
        return Err("no `---`/`+++` file markers found".into());
    }

    let mut patches = Vec::with_capacity(blocks.len());
    for (start, end) in blocks {
        let old_path = parse_side_path(&lines[start]["--- ".len()..]);
        let new_path = parse_side_path(&lines[start + 1]["+++ ".len()..]);
        let mut patch = FilePatch {
            is_new: old_path.is_none(),
            is_delete: new_path.is_none(),
            old_path,
            new_path,
            hunks: Vec::new(),
        };

        let mut i = start + 2;
        while i < end {
            let line = lines[i];
            if let Some(rest) = line.strip_prefix("@@") {
                if !rest.contains("@@") {
                    debug::log_to_file("apply_patch bad hunk header", diff);
                    return Err(format!("malformed hunk header: @@{rest}"));
                }
                i += 1;
                let mut body = Vec::new();
                while i < end && !lines[i].starts_with("@@") {
                    let l = lines[i];
                    if l.starts_with('\\') {
                        // "\ No newline at end of file" — line-level
                        // application does not need it; skip.
                        i += 1;
                        continue;
                    }
                    body.push(parse_body_line(l)?);
                    i += 1;
                }
                patch.hunks.push(Hunk { lines: body });
                continue;
            }
            if line.starts_with("Binary files ") || line == "GIT binary patch" {
                debug::log_to_file("apply_patch binary diff", diff);
                return Err("binary patches are not supported".into());
            }
            if line.starts_with("rename from ") || line.starts_with("rename to ") {
                debug::log_to_file("apply_patch rename/copy diff", diff);
                return Err("rename/copy patches are not supported".into());
            }
            i += 1;
        }
        patches.push(patch);
    }
    Ok(patches)
}

/// Classify one hunk body line by its leading marker character.
fn parse_body_line(line: &str) -> Result<BodyLine, String> {
    if let Some(rest) = line.strip_prefix(' ') {
        Ok(BodyLine::Context(rest.to_string()))
    } else if let Some(rest) = line.strip_prefix('+') {
        Ok(BodyLine::Add(rest.to_string()))
    } else if let Some(rest) = line.strip_prefix('-') {
        Ok(BodyLine::Del(rest.to_string()))
    } else {
        Err(format!("unrecognized hunk line: {line}"))
    }
}

/// Split content into lines for hunk application. The empty element produced
/// by `str::split('\n')` when the content ends in a newline is dropped, so
/// `["a", "b"]` is two lines regardless of the final newline.
fn split_lines(content: &str) -> Vec<String> {
    let mut lines: Vec<String> = content.split('\n').map(str::to_string).collect();
    if lines.last().is_some_and(|l| l.is_empty()) {
        lines.pop();
    }
    lines
}

/// First index `i` where `lines[i..i+needle.len()]` equals `needle`.
fn find_subslice(lines: &[String], needle: &[&str]) -> Option<usize> {
    if needle.len() > lines.len() {
        return None;
    }
    (0..=lines.len() - needle.len()).find(|&i| {
        needle
            .iter()
            .enumerate()
            .all(|(k, want)| lines[i + k] == *want)
    })
}

/// Apply one file patch against the current working-tree contents.
///
/// Reads the file (if any), matches each hunk's old-side lines (`context` +
/// `-`) against a contiguous block, and replaces it with the new-side lines
/// (`context` + `+`). This is the reliable path that `git apply --3way` was
/// supposed to provide: the patch merges onto whatever is in the working tree
/// now, regardless of the index or object database, and a single context line
/// is enough to anchor an insertion.
fn apply_file_patch(tree: &SourceTree, patch: &FilePatch) -> Result<AppliedFile, String> {
    let rel = patch.target_rel()?;
    if is_protected(&rel) {
        return Err(format!("patch touches protected path: {rel}"));
    }
    let abs = tree
        .resolve_for_write(Path::new(&rel))
        .map_err(|e| e.to_string())?;
    if tree.is_ignored(&abs) {
        return Err(format!("path is git-ignored: {}", abs.display()));
    }

    let existing = abs.exists();
    if patch.is_new {
        if existing {
            return Err(format!(
                "refusing to create {}: file already exists",
                abs.display()
            ));
        }
        let mut lines: Vec<String> = Vec::new();
        for hunk in &patch.hunks {
            let new_side: Vec<&str> = hunk
                .lines
                .iter()
                .filter(|l| !l.is_del())
                .map(BodyLine::text)
                .collect();
            lines.extend(new_side.into_iter().map(str::to_string));
        }
        let content = if lines.is_empty() {
            String::new()
        } else {
            format!("{}\n", lines.join("\n"))
        };
        return Ok(AppliedFile {
            abs,
            content: Some(content),
        });
    }

    if !existing {
        return Err(format!(
            "cannot apply patch: {} does not exist",
            abs.display()
        ));
    }
    let content =
        std::fs::read_to_string(&abs).map_err(|e| format!("reading {}: {e}", abs.display()))?;
    let had_trailing_newline = content.ends_with('\n');
    let mut lines = split_lines(&content);

    for hunk in &patch.hunks {
        let old_side: Vec<&str> = hunk
            .lines
            .iter()
            .filter(|l| !l.is_add())
            .map(BodyLine::text)
            .collect();
        let new_side: Vec<&str> = hunk
            .lines
            .iter()
            .filter(|l| !l.is_del())
            .map(BodyLine::text)
            .collect();

        if old_side.is_empty() {
            // Pure insertion with no context (e.g. a new file). Only
            // meaningful when there is no content to anchor against.
            if lines.is_empty() {
                lines.extend(new_side.into_iter().map(str::to_string));
                continue;
            }
            return Err(format!(
                "cannot apply hunk to {}: hunk has no context but the file is not empty",
                abs.display()
            ));
        }

        let n = old_side.len();
        let Some(pos) = find_subslice(&lines, &old_side) else {
            return Err(format!(
                "cannot apply hunk to {}: context does not match",
                abs.display()
            ));
        };
        let mut applied = Vec::with_capacity(lines.len() - n + new_side.len());
        applied.extend_from_slice(&lines[..pos]);
        applied.extend(new_side.into_iter().map(str::to_string));
        applied.extend_from_slice(&lines[pos + n..]);
        lines = applied;
    }

    if patch.is_delete {
        if !lines.is_empty() {
            return Err(format!(
                "deletion patch for {} leaves content behind",
                abs.display()
            ));
        }
        return Ok(AppliedFile { abs, content: None });
    }

    let mut out = lines.join("\n");
    if had_trailing_newline && !out.is_empty() {
        out.push('\n');
    }
    Ok(AppliedFile {
        abs,
        content: Some(out),
    })
}

/// Apply a unified diff to the working tree in pure Rust.
///
/// Why not `git apply`: the `--3way` merge depends on index/HEAD blobs that
/// are frequently unavailable here (hand-composed patches carry synthetic
/// `index` hashes), and the direct fallback refuses a hunk whose insertion
/// point is not anchored by trailing context — the exact "patch does not
/// apply" failure observed when patching a file that already has uncommitted
/// edits. Applying hunks directly against the current working-tree contents
/// handles the dirty-tree case naturally and never consults the object
/// database.
///
/// Matching is all-or-nothing: every hunk of every file is first matched
/// against in-memory copies; only when the whole diff applies are any files
/// written.
fn apply_unified_diff(tree: &SourceTree, diff: &str) -> Result<(), String> {
    let patches = parse_diff(diff).map_err(|e| format!("failed to parse patch: {e}"))?;
    let mut applied = Vec::with_capacity(patches.len());
    for patch in &patches {
        applied.push(apply_file_patch(tree, patch)?);
    }
    for file in &applied {
        match &file.content {
            Some(content) => {
                if let Some(parent) = file.abs.parent() {
                    std::fs::create_dir_all(parent)
                        .map_err(|e| format!("creating parent dirs: {e}"))?;
                }
                std::fs::write(&file.abs, content)
                    .map_err(|e| format!("writing {}: {e}", file.abs.display()))?;
            }
            None => {
                std::fs::remove_file(&file.abs)
                    .map_err(|e| format!("removing {}: {e}", file.abs.display()))?;
            }
        }
    }
    Ok(())
}

/// Is the patch's change already present in the working tree? True exactly
/// when applying the reversed patch succeeds — the "change already exists,
/// stop re-patching it" signal, computed in pure Rust.
#[cfg(test)]
fn diff_already_applied(tree: &SourceTree, diff: &str) -> bool {
    let Ok(patches) = parse_diff(diff) else {
        return false;
    };
    patches
        .iter()
        .all(|p| apply_file_patch(tree, &p.reversed()).is_ok())
}

/// Extract the repo-relative path from a `--- a/…` or `+++ b/…` line,
/// stripping any trailing tab metadata (timestamps from `git diff`).
fn diff_path_from_marker(rest: &str) -> String {
    rest.split('\t').next().unwrap_or(rest).trim().to_string()
}

/// Reject diffs that touch protected paths (`.ignore`, `.git*`).
fn diff_touches_protected(diff: &str) -> Option<String> {
    for line in diff.lines() {
        for prefix in ["+++ b/", "--- a/"] {
            if let Some(rest) = line.strip_prefix(prefix) {
                let rel = diff_path_from_marker(rest);
                if is_protected(&rel) {
                    return Some(rel);
                }
            }
        }
    }
    None
}

/// Tool: apply a unified diff to the repository working tree.
pub fn builtin_apply_patch(tree: Arc<SourceTree>) -> PortableDynamicTool {
    let json = json!({
        "type": "object",
        "properties": {
        "diff": {
            "type": "string",
            "description": "Unified diff against the current working tree"
        },
        "message": {
            "type": "string",
            "description": "Optional commit message"
        }
        },
        "required": ["diff"]
    });
    let _call_back = || ();
    PortableDynamicTool::new(
        "apply_patch",
        "Apply a unified diff (git diff format) to the repository working tree. The diff is \
	 parsed and applied directly against the current working-tree contents, so it works on \
	 top of other uncommitted changes — no clean tree or `git apply` needed. Application is \
	 all-or-nothing: if any hunk fails to match, nothing is written. If `message` is given, \
	 the change is committed with that message. Diffs that touch `.ignore` or `.git*` paths \
	 are refused. Changes are local commits only — never pushed.",
        json,
        move |args: serde_json::Value| {
            let tree = tree.clone();
            Box::pin(async move {
                let diff = args
                    .get("diff")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| ToolExecutionError::invalid_args("missing string field 'diff'"))?
                    .to_string();
                let message = args
                    .get("message")
                    .and_then(|v| v.as_str())
                    .filter(|m| !m.trim().is_empty())
                    .map(String::from);

                if let Some(rel) = diff_touches_protected(&diff) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "diff touches protected path: {rel}"
                    )));
                }

                apply_unified_diff(&tree, &diff)
                    .map_err(|e| ToolExecutionError::provider(format!("apply failed: {e}")))?;

                let mut out = String::from("patch applied");
                if let Some(msg) = message {
                    // Stage everything so the commit captures the patch (this
                    // also covers new files and initial commits).
                    git_run(tree.root(), &["add", "-A"])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let (_, stderr) = git_run(tree.root(), &["commit", "-m", &msg])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let note = if stderr.trim().is_empty() {
                        "committed".to_string()
                    } else {
                        format!("committed ({})", stderr.trim())
                    };
                    out.push_str(&format!("\n{note}"));
                }
                Ok(ToolOutput::text(out))
            })
        },
    )
}

/// Tool: write a text file inside the repository.
pub fn builtin_write_file(tree: Arc<SourceTree>) -> PortableDynamicTool {
    PortableDynamicTool::new(
        "write_file",
        "Write a text file inside the git repository. `path` is relative to the repo root. \
	 Refused: paths outside the repo, git-ignored paths, `.ignore`, `.gitignore`, anything \
	 under `.git/`. If `message` is given, the change is committed with that message. \
	 Local commits only — never pushed.",
        json!({
            "type": "object",
            "properties": {
            "path": {
                "type": "string",
                "description": "Path relative to the repo root"
            },
            "content": {
                "type": "string",
                "description": "Full file contents"
            },
            "message": {
                "type": "string",
                "description": "Optional commit message"
            }
            },
            "required": ["path", "content"]
        }),
        move |args: serde_json::Value| {
            let tree = tree.clone();
            Box::pin(async move {
                let rel = args
                    .get("path")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| ToolExecutionError::invalid_args("missing string field 'path'"))?
                    .to_string();
                let content = args
                    .get("content")
                    .and_then(|v| v.as_str())
                    .ok_or_else(|| {
                        ToolExecutionError::invalid_args("missing string field 'content'")
                    })?
                    .to_string();
                let message = args
                    .get("message")
                    .and_then(|v| v.as_str())
                    .filter(|m| !m.trim().is_empty())
                    .map(String::from);

                if is_protected(&rel) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "path is protected: {rel}"
                    )));
                }

                // Escape/ignore checks via SourceTree (handles `..`, absolute
                // paths, symlink escapes, and ignore rules).
                let abs = tree
                    .resolve_for_write(Path::new(&rel))
                    .map_err(map_source_err)?;
                if tree.is_ignored(&abs) {
                    return Err(ToolExecutionError::permission_denied(format!(
                        "path is git-ignored: {}",
                        abs.display()
                    )));
                }

                if let Some(parent) = abs.parent() {
                    std::fs::create_dir_all(parent).map_err(|e| {
                        ToolExecutionError::provider(format!("creating parent dirs: {e}"))
                    })?;
                }
                std::fs::write(&abs, &content).map_err(|e| {
                    ToolExecutionError::provider(format!("writing {}: {e}", abs.display()))
                })?;

                let mut out = format!("wrote {} ({} bytes)", abs.display(), content.len());
                if let Some(msg) = message {
                    git_run(tree.root(), &["add", "--", &rel])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let (_, stderr) = git_run(tree.root(), &["commit", "-m", &msg])
                        .await
                        .map_err(ToolExecutionError::provider)?;
                    let note = if stderr.trim().is_empty() {
                        "committed".to_string()
                    } else {
                        format!("committed ({})", stderr.trim())
                    };
                    out.push_str(&format!("\n{note}"));
                }
                Ok(ToolOutput::text(out))
            })
        },
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::source::testutil::Fixture;

    /// Make a real git repo out of `fx` with a configured identity and one
    /// initial commit, so `git status --porcelain` reflects a clean tree.
    async fn init_committed_repo(fx: &Fixture) {
        git_run(&fx.dir, &["init", "-q"]).await.expect("git init");
        git_run(&fx.dir, &["config", "user.email", "test@hanihi.local"])
            .await
            .expect("config email");
        git_run(&fx.dir, &["config", "user.name", "hanihi-test"])
            .await
            .expect("config name");
        git_run(&fx.dir, &["add", "-A"]).await.expect("git add");
        git_run(&fx.dir, &["commit", "-q", "-m", "init"])
            .await
            .expect("git commit");
    }

    /// A minimal single-file diff (with `diff --git` header) against
    /// `src/main.rs`. The synthetic `index` hashes are ignored by the
    /// pure-Rust applier.
    fn header_diff() -> &'static str {
        "diff --git a/src/main.rs b/src/main.rs\nindex 8b13789..0000000 100644\n--- a/src/main.rs\n+++ b/src/main.rs\n@@ -1 +1,2 @@\n fn main() {}\n+// patched\n"
    }

    #[tokio::test]
    async fn write_file_writes_new_file() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());
        let out = tool
            .execute(serde_json::json!({
            "path": "src/new.rs",
            "content": "pub fn added() {}\n"
            }))
            .await
            .expect("write succeeds");
        let rendered = out.render();
        assert!(rendered.contains("src/new.rs"), "got: {rendered}");
        let written = std::fs::read_to_string(fx.dir.join("src/new.rs")).unwrap();
        assert_eq!(written, "pub fn added() {}\n");
    }

    #[tokio::test]
    async fn write_file_refuses_protected_and_ignored() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());

        let err = tool
            .execute(serde_json::json!({
            "path": ".ignore",
            "content": "junk\n"
            }))
            .await
            .expect_err("protected path must fail");
        assert!(err.to_string().contains("protected"), "got: {err}");

        let err = tool
            .execute(serde_json::json!({
            "path": "target/debug/junk.rs",
            "content": "junk\n"
            }))
            .await
            .expect_err("ignored path must fail");
        assert!(err.to_string().contains("git-ignored"), "got: {err}");
    }

    #[tokio::test]
    async fn write_file_refuses_escapes() {
        let fx = Fixture::new();
        let tool = builtin_write_file(fx.tree());
        let name = format!("hanihi-write-outside-{}", uuid::Uuid::new_v4());
        let err = tool
            .execute(serde_json::json!({
            "path": format!("../{name}"),
            "content": "x"
            }))
            .await
            .expect_err("escape must fail");
        assert!(err.to_string().contains("escapes"), "got: {err}");
    }

    #[tokio::test]
    async fn apply_patch_applies_and_commits() {
        let fx = Fixture::new();
        init_committed_repo(&fx).await;
        let tool = builtin_apply_patch(fx.tree());
        let out = tool
            .execute(serde_json::json!({
            "diff": header_diff(),
            "message": "test patch"
            }))
            .await
            .unwrap_or_else(|e| panic!("apply failed: {e}"));
        let rendered = out.render();
        assert!(rendered.contains("patch applied"), "got: {rendered}");
        assert!(rendered.contains("committed"), "got: {rendered}");
        let main = std::fs::read_to_string(fx.dir.join("src/main.rs")).unwrap();
        assert!(main.contains("// patched"));

        // Committed: working tree must be clean.
        let (stdout, _) = git_run(&fx.dir, &["status", "--porcelain"]).await.unwrap();
        assert_eq!(stdout.trim(), "", "expected clean tree, got: {stdout}");
    }

    #[tokio::test]
    async fn apply_patch_works_on_dirty_tree() {
        let fx = Fixture::new();
        init_committed_repo(&fx).await;

        // The case plain `git apply` refused: an uncommitted edit already
        // sits in the target file and the hunk has no trailing context. The
        // applier must insert the patch on top of the local edit instead of
        // refusing.
        std::fs::write(fx.dir.join("src/main.rs"), "fn main() {}\n// local\n").unwrap();

        let tool = builtin_apply_patch(fx.tree());
        tool.execute(serde_json::json!({ "diff": header_diff() }))
            .await
            .unwrap_or_else(|e| panic!("apply over dirty tree must succeed: {e}"));

        let main = std::fs::read_to_string(fx.dir.join("src/main.rs")).unwrap();
        assert!(main.contains("// patched"), "got: {main}");
        // The pre-existing uncommitted edit is preserved alongside the patch.
        assert!(main.contains("// local"), "got: {main}");
    }

    #[tokio::test]
    async fn apply_patch_adds_new_file_on_clean_tree() {
        let fx = Fixture::new();
        init_committed_repo(&fx).await;

        // Adding a brand-new file (not already present) must work.
        let add = "diff --git a/src/extra.rs b/src/extra.rs\nnew file mode 100644\n--- /dev/null\n+++ b/src/extra.rs\n@@ -0,0 +1 @@\n+pub fn extra() {}\n";

        let tool = builtin_apply_patch(fx.tree());
        tool.execute(serde_json::json!({ "diff": add }))
            .await
            .unwrap_or_else(|e| panic!("apply must succeed adding a new file: {e}"));

        let extra = std::fs::read_to_string(fx.dir.join("src/extra.rs")).unwrap();
        assert_eq!(extra, "pub fn extra() {}\n");
    }

    #[tokio::test]
    async fn apply_patch_rejects_bad_diff_and_protected_paths() {
        let fx = Fixture::new();
        let tool = builtin_apply_patch(fx.tree());

        let err = tool
            .execute(serde_json::json!({ "diff": "not a diff at all" }))
            .await
            .expect_err("bad diff must fail");
        assert!(err.to_string().contains("failed"), "got: {err}");

        let err = tool
	    .execute(serde_json::json!({ "diff": "--- a/.ignore\n+++ b/.ignore\n@@ -1 +1 @@\n-x\n+y\n" }))
	    .await
	    .expect_err("protected diff must fail");
        assert!(err.to_string().contains("protected"), "got: {err}");
    }

    #[test]
    fn protected_path_detection() {
        assert!(is_protected(".ignore"));
        assert!(is_protected(".gitignore"));
        assert!(is_protected(".git/config"));
        assert!(is_protected(".git"));
        assert!(!is_protected("src/main.rs"));
        assert!(!is_protected("docs/.ignore.md"));
    }

    #[test]
    fn diff_protected_scan() {
        assert_eq!(
            diff_touches_protected("--- a/src/main.rs\n+++ b/src/main.rs\n"),
            None
        );
        assert_eq!(
            diff_touches_protected("+++ b/.ignore\n"),
            Some(".ignore".to_string())
        );
        // Path with tab (git diff metadata) is still caught.
        assert_eq!(
            diff_touches_protected("+++ b/.git/config\t2026-01-01\n"),
            Some(".git/config".to_string())
        );
    }

    #[tokio::test]
    async fn diff_already_applied_detects_existing_change() {
        let fx = Fixture::new();
        init_committed_repo(&fx).await;
        let tree = fx.tree();

        // Nothing applied yet: the change is not present.
        assert!(!diff_already_applied(&tree, header_diff()));

        // Apply it, then the change is present.
        apply_unified_diff(&tree, header_diff()).expect("apply");
        assert!(diff_already_applied(&tree, header_diff()));
    }
}

//! Source tree access: read and list code inside a git repository,
//! filtered by the repository's ignore rules (`.gitignore`, `.ignore`,
//! `.git/info/exclude`) via the [`ignore`] crate.
//!
//! The agent's view of a repository is restricted to what git itself
//! would track: ignored paths (`target/`, build directories, ...) are
//! invisible to both directory listing and targeted reads.
//!
//! hānihi maintains its own `.ignore` file at the repo root (see
//! [`ensure_ignore_file`]): same syntax as `.gitignore`, but git-agnostic
//! and managed by hānihi. The repo's `.gitignore` is respected but never
//! written.

use std::fmt;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use ignore::gitignore::{Gitignore, GitignoreBuilder};
use ignore::{Match, Walk, WalkBuilder};

/// Maximum number of bytes [`SourceTree::read`] returns for one file.
pub const MAX_READ_BYTES: usize = 64 * 1024;

/// Marker line used to recognise an existing hānihi-managed `.ignore`.
const HANIHI_HEADER: &str = "# hānihi-managed ignore file (agent read policy)\n";

/// Programming languages hānihi can recognise and write templates for.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Language {
    /// Rust — detected by `Cargo.toml`.
    Rust,
    /// C or C++ — detected by `CMakeLists.txt`/`Makefile`/C-family sources.
    C,
}

impl Language {
    /// `.ignore`-syntax patterns for generated artifacts of this language.
    pub fn template(self) -> &'static str {
        match self {
            Language::Rust => "target/\n**/*.rs.bk\n",
            Language::C => {
                "build/\ncmake-build-*/\nCMakeFiles/\n\
                 *.o\n*.obj\n*.a\n*.so\n*.dylib\n*.exe\n\
                 *.gcda\n*.gcno\n\
                 a.out\n.cache/\n\
                 # compile_commands.json — sometimes committed; useful for the agent\n"
            }
        }
    }
}

/// Errors produced by [`SourceTree`].
#[derive(Debug)]
pub enum SourceError {
    /// No repository found (no `.git` at or above the start path).
    NotARepository(PathBuf),
    /// The requested path does not exist.
    NotFound(PathBuf),
    /// The requested path resolves outside the repository root.
    Escape(PathBuf),
    /// The requested path is excluded by an ignore rule.
    Ignored(PathBuf),
    /// I/O failure.
    Io(io::Error),
    /// Error from the `ignore` crate (parsing, walking).
    Ignore(ignore::Error),
}

impl fmt::Display for SourceError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            SourceError::NotARepository(p) => {
                write!(f, "no git repository found at or above {}", p.display())
            }
            SourceError::NotFound(p) => write!(f, "no such path: {}", p.display()),
            SourceError::Escape(p) => write!(f, "path escapes the repository: {}", p.display()),
            SourceError::Ignored(p) => write!(f, "path is ignored: {}", p.display()),
            SourceError::Io(e) => write!(f, "io error: {e}"),
            SourceError::Ignore(e) => write!(f, "ignore error: {e}"),
        }
    }
}

impl std::error::Error for SourceError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            SourceError::Io(e) => Some(e),
            SourceError::Ignore(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for SourceError {
    fn from(e: io::Error) -> Self {
        SourceError::Io(e)
    }
}

impl From<ignore::Error> for SourceError {
    fn from(e: ignore::Error) -> Self {
        SourceError::Ignore(e)
    }
}

/// A git repository the agent may read, filtered by ignore rules.
#[derive(Debug)]
pub struct SourceTree {
    root: PathBuf,
    matcher: Gitignore,
}

impl SourceTree {
    /// Locate the repository containing the current directory and open it.
    pub fn open() -> Result<Self, SourceError> {
        let cwd = std::env::current_dir().map_err(SourceError::Io)?;
        let root = find_repo_root(&cwd).ok_or(SourceError::NotARepository(cwd))?;
        Self::open_at(&root)
    }

    /// Open the repository rooted at `root` (must contain `.git`).
    pub fn open_at(root: &Path) -> Result<Self, SourceError> {
        let root = root.canonicalize().map_err(SourceError::Io)?;
        if !root.join(".git").exists() {
            return Err(SourceError::NotARepository(root));
        }
        // Maintain `.ignore` first so the matcher below picks it up.
        ensure_ignore_file(&root)?;
        let matcher = build_matcher(&root)?;
        Ok(Self { root, matcher })
    }

    /// The canonical repository root.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Whether `abs` (an absolute path) is excluded by ignore rules.
    /// Paths outside the repository count as ignored.
    pub fn is_ignored(&self, abs: &Path) -> bool {
        let Ok(rel) = abs.strip_prefix(&self.root) else {
            return true;
        };
        let is_dir = abs.is_dir();
        matches!(
            self.matcher.matched_path_or_any_parents(rel, is_dir),
            Match::Ignore(_)
        )
    }

    /// Iterate visible entries under `rel`, honouring ignore rules and a
    /// recursion `max_depth` (0 = just the directory itself). The walker
    /// never descends into `.git`.
    pub fn walk(&self, rel: &Path, max_depth: usize) -> Result<Walk, SourceError> {
        let base = self.resolve(rel)?;
        Ok(WalkBuilder::new(&base)
            .standard_filters(true)
            .hidden(false) // dotfiles stay visible; ignore rules are the policy
            .require_git(true)
            .max_depth(Some(max_depth))
            .sort_by_file_path(|a, b| a.cmp(b))
            .filter_entry(|e| e.file_name() != ".git")
            .build())
    }

    /// Read a text file under `rel`, honouring ignore rules and the size
    /// cap. Returns the (possibly truncated) contents.
    pub fn read(&self, rel: &Path) -> Result<String, SourceError> {
        let canon = self.resolve(rel)?;
        if !canon.is_file() {
            return Err(SourceError::NotFound(rel.to_path_buf()));
        }
        if self.is_ignored(&canon) {
            return Err(SourceError::Ignored(rel.to_path_buf()));
        }
        let bytes = fs::read(&canon).map_err(SourceError::Io)?;
        let text = String::from_utf8_lossy(&bytes);
        let cut = text.floor_char_boundary(MAX_READ_BYTES);
        let mut out = String::with_capacity(cut + 64);
        out.push_str(&text[..cut]);
        if bytes.len() > MAX_READ_BYTES {
            let note = format!("\n…[truncated, {} bytes total]", bytes.len());
            out.push_str(&note);
        }
        Ok(out)
    }

    /// Resolve `rel` inside the repository root to a canonical absolute
    /// path, refusing escapes.
    pub(crate) fn resolve(&self, rel: &Path) -> Result<PathBuf, SourceError> {
        let abs = self.root.join(rel);
        let canon = abs
            .canonicalize()
            .map_err(|_| SourceError::NotFound(rel.to_path_buf()))?;
        if !canon.starts_with(&self.root) {
            return Err(SourceError::Escape(rel.to_path_buf()));
        }
        Ok(canon)
    }

    /// Resolve a repository-relative path for writing, refusing escapes.
    ///
    /// Unlike [`SourceTree::resolve`], the target need not exist yet: the
    /// nearest existing ancestor is canonicalized (resolving any symlinks)
    /// and the non-existent tail is re-appended. Absolute paths and any
    /// `..` component are refused before touching the filesystem.
    pub fn resolve_for_write(&self, rel: &Path) -> Result<PathBuf, SourceError> {
        for comp in rel.components() {
            if matches!(
                comp,
                std::path::Component::ParentDir
                    | std::path::Component::RootDir
                    | std::path::Component::Prefix(_)
            ) {
                return Err(SourceError::Escape(rel.to_path_buf()));
            }
        }

        let abs = self.root.join(rel);
        let mut existing = abs.clone();
        let mut tail: Vec<std::ffi::OsString> = Vec::new();
        loop {
            match existing.canonicalize() {
                Ok(canon) => {
                    let mut resolved = canon;
                    for comp in tail.iter().rev() {
                        resolved.push(comp);
                    }
                    if !resolved.starts_with(&self.root) {
                        return Err(SourceError::Escape(rel.to_path_buf()));
                    }
                    return Ok(resolved);
                }
                Err(_) => {
                    let Some(name) = existing.file_name() else {
                        return Err(SourceError::NotFound(rel.to_path_buf()));
                    };
                    tail.push(name.to_os_string());
                    if !existing.pop() {
                        return Err(SourceError::NotFound(rel.to_path_buf()));
                    }
                }
            }
        }
    }
}

/// Nearest ancestor of `start` that contains `.git` (a directory, or a
/// file — the latter covers worktrees).
fn find_repo_root(start: &Path) -> Option<PathBuf> {
    let mut dir = Some(start);
    while let Some(d) = dir {
        if d.join(".git").exists() {
            return Some(d.to_path_buf());
        }
        dir = d.parent();
    }
    None
}

/// Build the ignore matcher from `.gitignore`, `.ignore`, and
/// `.git/info/exclude` (existing files only — `GitignoreBuilder::add`
/// errors on missing files).
fn build_matcher(root: &Path) -> Result<Gitignore, SourceError> {
    let mut builder = GitignoreBuilder::new(root);
    for name in [".gitignore", ".ignore"] {
        let path = root.join(name);
        if path.exists()
            && let Some(err) = builder.add(&path)
        {
            return Err(SourceError::Ignore(err));
        }
    }
    let exclude = root.join(".git/info/exclude");
    if exclude.exists()
        && let Some(err) = builder.add(&exclude)
    {
        return Err(SourceError::Ignore(err));
    }
    builder.build().map_err(SourceError::Ignore)
}

/// Ensure the repo has a `.ignore` file describing hānihi's read policy.
///
/// Never clobbers existing content: the language template header is only
/// prepended when absent, and everything the user wrote is preserved.
fn ensure_ignore_file(root: &Path) -> Result<(), SourceError> {
    let path = root.join(".ignore");
    let existing = if path.exists() {
        fs::read_to_string(&path).map_err(SourceError::Io)?
    } else {
        String::new()
    };

    let mut changed = false;
    let mut content = existing;
    if !content.contains(HANIHI_HEADER) {
        let mut tpl = String::from(HANIHI_HEADER);
        for lang in detect_languages(root) {
            tpl.push_str(lang.template());
        }
        tpl.push('\n');
        content = format!("{tpl}{content}");
        changed = true;
    }
    if changed {
        fs::write(&path, content).map_err(SourceError::Io)?;
    }
    Ok(())
}

/// Detect programming languages from marker files and source extensions,
/// scanning up to two levels deep (catches workspace members).
fn detect_languages(root: &Path) -> Vec<Language> {
    let mut langs = Vec::new();
    let mut has_c = false;
    let walker = WalkBuilder::new(root)
        .standard_filters(true)
        .hidden(false)
        .require_git(true)
        .max_depth(Some(2))
        .build();
    for entry in walker.flatten() {
        let path = entry.path();
        if path == root {
            continue;
        }
        let name = entry.file_name().to_string_lossy();
        match name.as_ref() {
            "Cargo.toml" => push_lang(&mut langs, Language::Rust),
            "CMakeLists.txt" | "Makefile" | "meson.build" => has_c = true,
            _ => {
                let ext = path
                    .extension()
                    .and_then(|e| e.to_str())
                    .unwrap_or("")
                    .to_ascii_lowercase();
                if matches!(
                    ext.as_str(),
                    "c" | "h" | "cpp" | "cc" | "cxx" | "hpp" | "hh"
                ) {
                    has_c = true;
                }
            }
        }
    }
    if has_c {
        push_lang(&mut langs, Language::C);
    }
    langs
}

fn push_lang(langs: &mut Vec<Language>, lang: Language) {
    if !langs.contains(&lang) {
        langs.push(lang);
    }
}

#[cfg(test)]
pub(crate) mod testutil {
    use super::*;
    use std::fs;
    use std::sync::Arc;

    /// Throwaway git repo with an ignored `target/` dir.
    pub(crate) struct Fixture {
        pub(crate) dir: PathBuf,
    }

    impl Fixture {
        pub(crate) fn new() -> Self {
            let dir = std::env::temp_dir().join(format!("hanihi-src-{}", uuid::Uuid::new_v4()));
            fs::create_dir_all(dir.join(".git")).unwrap();
            fs::create_dir_all(dir.join("src")).unwrap();
            fs::create_dir_all(dir.join("target/debug")).unwrap();
            fs::write(dir.join(".gitignore"), "target/\n").unwrap();
            fs::write(dir.join("Cargo.toml"), "[package]\nname = \"fixture\"\n").unwrap();
            fs::write(dir.join("src/main.rs"), "fn main() {}\n").unwrap();
            fs::write(dir.join("target/debug/junk.rs"), "junk\n").unwrap();
            Self { dir }
        }

        pub(crate) fn tree(&self) -> Arc<SourceTree> {
            Arc::new(SourceTree::open_at(&self.dir).expect("fixture is a git repo"))
        }
    }

    impl Drop for Fixture {
        fn drop(&mut self) {
            fs::remove_dir_all(&self.dir).unwrap_or(());
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn walk_excludes_ignored_paths() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        let paths: Vec<PathBuf> = tree
            .walk(Path::new("."), 4)
            .unwrap()
            .filter_map(Result::ok)
            .map(|e| e.path().to_path_buf())
            .collect();
        assert!(paths.iter().any(|p| p.ends_with("src/main.rs")));
        assert!(paths.iter().any(|p| p.ends_with("Cargo.toml")));
        assert!(!paths.iter().any(|p| p.ends_with("target")));
        assert!(!paths.iter().any(|p| p.ends_with("junk.rs")));
        assert!(
            !paths
                .iter()
                .any(|p| p.components().any(|c| c.as_os_str() == ".git"))
        );
    }

    #[test]
    fn walk_is_shallow_at_depth_one() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        let paths: Vec<PathBuf> = tree
            .walk(Path::new("."), 1)
            .unwrap()
            .filter_map(Result::ok)
            .map(|e| e.path().to_path_buf())
            .collect();
        // src/ is listed, src/main.rs is not.
        assert!(paths.iter().any(|p| p.ends_with("src")));
        assert!(!paths.iter().any(|p| p.ends_with("src/main.rs")));
    }

    #[test]
    fn read_honours_ignore_rules() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        let main = tree.read(Path::new("src/main.rs")).unwrap();
        assert!(main.contains("fn main"));
        match tree.read(Path::new("target/debug/junk.rs")) {
            Err(SourceError::Ignored(_)) => {}
            other => panic!("expected Ignored, got {other:?}"),
        }
    }

    #[test]
    fn read_refuses_escapes() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        let name = format!("hanihi-outside-{}", uuid::Uuid::new_v4());
        let outside = std::env::temp_dir().join(&name);
        fs::write(&outside, "secret").unwrap();
        let rel = Path::new("..").join(&name);
        match tree.read(&rel) {
            Err(SourceError::Escape(_)) => {}
            other => panic!("expected Escape, got {other:?}"),
        }
        fs::remove_file(&outside).unwrap_or(());
    }

    #[test]
    fn read_truncates_large_files() {
        let fx = testutil::Fixture::new();
        let tree = fx.tree();
        fs::write(fx.dir.join("big.rs"), "x".repeat(MAX_READ_BYTES + 4096)).unwrap();
        let out = tree.read(Path::new("big.rs")).unwrap();
        assert!(out.contains("[truncated"));
        assert!(out.len() < MAX_READ_BYTES + 4096);
    }

    #[test]
    fn open_requires_a_repository() {
        let dir = std::env::temp_dir().join(format!("hanihi-norepo-{}", uuid::Uuid::new_v4()));
        fs::create_dir_all(&dir).unwrap();
        let err = SourceTree::open_at(&dir).unwrap_err();
        assert!(matches!(err, SourceError::NotARepository(_)));
        fs::remove_dir_all(&dir).unwrap_or(());
    }

    #[test]
    fn find_repo_root_walks_up() {
        let fx = testutil::Fixture::new();
        assert_eq!(find_repo_root(&fx.dir.join("src")), Some(fx.dir.clone()));
    }

    #[test]
    fn find_repo_root_returns_none_outside_repos() {
        let dir = std::env::temp_dir().join(format!("hanihi-norepo-{}", uuid::Uuid::new_v4()));
        fs::create_dir_all(&dir).unwrap();
        assert_eq!(find_repo_root(&dir), None);
        fs::remove_dir_all(&dir).unwrap_or(());
    }

    #[test]
    fn ensure_ignore_file_bootstraps_rust_template() {
        let fx = testutil::Fixture::new();
        fx.tree(); // open_at runs ensure_ignore_file
        let content = fs::read_to_string(fx.dir.join(".ignore")).unwrap();
        assert!(content.contains(HANIHI_HEADER));
        assert!(content.contains("target/"));
    }

    #[test]
    fn ensure_ignore_file_preserves_user_content() {
        let fx = testutil::Fixture::new();
        fs::write(fx.dir.join(".ignore"), "vendor/\n").unwrap();
        fx.tree();
        let content = fs::read_to_string(fx.dir.join(".ignore")).unwrap();
        assert!(content.contains("vendor/"));
        assert!(content.contains(HANIHI_HEADER));
        // Opening again must not duplicate the template.
        fx.tree();
        let content2 = fs::read_to_string(fx.dir.join(".ignore")).unwrap();
        assert_eq!(content, content2);
    }
}

//! # hanihi-session
//!
//! Read-only session introspection for hānihi. Prints the same
//! `/session` summary the REPL shows — session name/id, current turn,
//! the `[turn N | tool calls | tokens in/out]` line, and cumulative
//! token usage — by reading a session directory's `session.json` and
//! `events.jsonl` directly, without connecting to any model or taking
//! the session lock.

use std::path::{Path, PathBuf};

/// Data needed to reproduce a session summary line.
struct SessionInfo {
    id: String,
    name: String,
    model: String,
    turn: u64,
    /// Most recent completed turn's token usage (input, output).
    last_in: u64,
    last_out: u64,
    /// Tool calls in the most recent completed turn.
    last_tool_calls: u64,
    /// Cumulative token usage across all turns.
    cum_in: u64,
    cum_out: u64,
}

/// Raw fields we need out of `session.json`.
#[derive(serde::Deserialize)]
struct Meta {
    #[serde(default)]
    id: String,
    #[serde(default)]
    name: String,
    #[serde(default)]
    model: String,
}

fn main() {
    // Positional: working dir (default ./working) then session name
    // (default default-session). Simplest possible CLI, no clap dependency.
    let args: Vec<String> = std::env::args().skip(1).collect();
    let (working_dir, session_name) = match args.as_slice() {
        [] => (PathBuf::from("./working"), "default-session".to_string()),
        [name] => (PathBuf::from("./working"), name.clone()),
        [dir, name] => (PathBuf::from(dir), name.clone()),
        _ => {
            eprintln!("usage: hanihi-session [WORKING_DIR] [SESSION_NAME]");
            std::process::exit(2);
        }
    };

    match print_session(&working_dir, &session_name) {
        Ok(()) => {}
        Err(e) => {
            eprintln!("error: {e}");
            std::process::exit(1);
        }
    }
}

fn print_session(working_dir: &Path, name: &str) -> Result<(), String> {
    let dir = working_dir.join("sessions").join(name);
    let meta = read_meta(&dir)?;
    let events = read_events(&dir)?;

    let info = summarize(&meta, &events);

    // Mirror the REPL's `/session` output.
    println!(
        "session: '{}' (id={}) turn={} max_turns=(n/a outside REPL)",
        info.name, info.id, info.turn
    );
    println!(
        "[turn {} | tool calls: {} | tokens: {} in / {} out]",
        info.turn, info.last_tool_calls, info.last_in, info.last_out
    );
    println!(
        "cumulative tokens: {} in / {} out | model: {}",
        info.cum_in, info.cum_out, info.model
    );
    Ok(())
}

/// Read and parse `session.json`.
fn read_meta(dir: &Path) -> Result<Meta, String> {
    let path = dir.join("session.json");
    let bytes = std::fs::read(&path).map_err(|e| format!("reading {}: {e}", path.display()))?;
    serde_json::from_slice(&bytes).map_err(|e| format!("parsing {}: {e}", path.display()))
}

/// Parse each `events.jsonl` line into the minimal shape we need.
fn read_events(dir: &Path) -> Result<Vec<serde_json::Value>, String> {
    let path = dir.join("events.jsonl");
    let content =
        std::fs::read_to_string(&path).map_err(|e| format!("reading {}: {e}", path.display()))?;
    let mut entries = Vec::new();
    for (i, line) in content.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let value: serde_json::Value =
            serde_json::from_str(line).map_err(|e| format!("events.jsonl line {}: {e}", i + 1))?;
        entries.push(value);
    }
    Ok(entries)
}

/// Fold the events into a [`SessionInfo`].
fn summarize(meta: &Meta, events: &[serde_json::Value]) -> SessionInfo {
    let mut info = SessionInfo {
        id: meta.id.clone(),
        name: meta.name.clone(),
        model: meta.model.clone(),
        turn: 0,
        last_in: 0,
        last_out: 0,
        last_tool_calls: 0,
        cum_in: 0,
        cum_out: 0,
    };

    for entry in events {
        let Some(kind) = entry.get("kind").and_then(|k| k.as_str()) else {
            continue;
        };
        let Some(turn) = entry.get("turn").and_then(|t| t.as_u64()) else {
            continue;
        };
        let Some(data) = entry.get("data") else {
            continue;
        };

        match kind {
            "turn_complete" => {
                info.turn = turn;
                info.last_in = 0;
                info.last_out = 0;
                info.last_tool_calls = data.get("tool_calls").and_then(|t| t.as_u64()).unwrap_or(0);
            }
            "llm_response" if turn == info.turn => {
                if let Some(usage) = data.get("usage") {
                    info.last_in += usage
                        .get("input_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                    info.last_out += usage
                        .get("output_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                    info.cum_in += usage
                        .get("input_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                    info.cum_out += usage
                        .get("output_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                }
            }
            "llm_response" => {
                if let Some(usage) = data.get("usage") {
                    info.cum_in += usage
                        .get("input_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                    info.cum_out += usage
                        .get("output_tokens")
                        .and_then(|v| v.as_u64())
                        .unwrap_or(0);
                }
            }
            _ => {}
        }
    }

    info
}

//! # hanihi-session-analyser
//!
//! CLI for [`hanihi_session_analyser`]: reads a session's `events.jsonl`
//! directly (no model connection, no session lock) and prints per-turn
//! and aggregate metrics.

use std::path::PathBuf;

use hanihi_session_analyser::{analyse, read_log};

fn main() {
    // Positional: working dir (default ./working), then session name
    // (default default-session). Simple CLI, no clap dependency.
    let args: Vec<String> = std::env::args().skip(1).collect();
    let (working_dir, session_name) = match args.as_slice() {
        [] => (PathBuf::from("./working"), "default-session".to_string()),
        [name] => (PathBuf::from("./working"), name.clone()),
        [dir, name] => (PathBuf::from(dir), name.clone()),
        _ => {
            eprintln!("usage: hanihi-session-analyser [WORKING_DIR] [SESSION_NAME]");
            std::process::exit(2);
        }
    };

    let log_path = working_dir.join("sessions").join(&session_name).join("events.jsonl");

    let entries = match read_log(&log_path) {
        Ok(entries) => entries,
        Err(e) => {
            eprintln!("error reading {}: {e}", log_path.display());
            std::process::exit(1);
        }
    };

    let metrics = analyse(&entries);

    if metrics.turns.is_empty() {
        println!("session '{session_name}': no completed turns");
        return;
    }

    for turn in &metrics.turns {
        println!(
            "[turn {} | tool calls: {} | tokens: {} in / {} out | model calls: {}]",
            turn.turn, turn.tool_calls, turn.tokens_in, turn.tokens_out, turn.model_calls
        );
    }

    println!(
        "turns: {} | cumulative tokens: {} in / {} out | tool calls: {} | errors: {}",
        metrics.turns.len(),
        metrics.tokens_in,
        metrics.tokens_out,
        metrics.tool_calls,
        metrics.errors
    );

    if metrics.latency.calls > 0 {
        println!(
            "latency: {} model call(s), avg {}ms, min {}ms, max {}ms",
            metrics.latency.calls,
            metrics.latency.total_ms / metrics.latency.calls as i64,
            metrics.latency.min_ms,
            metrics.latency.max_ms
        );
    }
}

//! Session management: named, persistent conversation containers with
//! append-only JSONL event logs.
//!
//! A [`Session`] holds the on-disk state (metadata, event log, lock) for a
//! named conversation. It does not own an [`Agent`]; the caller passes the
//! agent to [`Session::run`], which wraps the agent loop with full logging.
//!
//! [`SessionManager`] owns the working directory and handles creation,
//! opening, and closing of sessions.
//!
//! [`Agent`]: crate::agent::Agent

pub mod lock;
pub mod log;

use std::collections::HashMap;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use chrono::Utc;
use rig::completion::message::{ToolCall, ToolFunction};
use rig::completion::{AssistantContent, CompletionModel, Message};
use tokio::sync::mpsc;
use uuid::Uuid;

use self::lock::SessionGuard;
use self::log::{
    ErrorStage, LlmResponseData, LogEntry, LogWriter, ToolCallData, ToolExecutionData, UsageData,
};
use crate::agent::{Agent, StreamEvent, TurnSummary, messages_for_log};
use crate::error::AgentError;

/// Errors produced by session operations.
#[derive(Debug)]
pub enum SessionError {
    /// The session name is reserved and cannot be created manually.
    ReservedName(String),
    /// A session with this name already exists.
    AlreadyExists(String),
    /// The requested session was not found.
    NotFound(String),
    /// The session is locked by another process.
    Locked(String),
    /// An I/O error occurred.
    Io(io::Error),
    /// A JSON (de)serialization error occurred.
    Json(serde_json::Error),
    /// A line in the event log could not be parsed.
    LogLine { line: usize, message: String },
}

impl std::fmt::Display for SessionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SessionError::ReservedName(name) => {
                write!(f, "'{name}' is reserved and cannot be created manually")
            }
            SessionError::AlreadyExists(name) => {
                write!(f, "session '{name}' already exists")
            }
            SessionError::NotFound(name) => {
                write!(
                    f,
                    "session '{name}' not found — use --new-session to create it"
                )
            }
            SessionError::Locked(name) => {
                write!(f, "session '{name}' is locked by another process")
            }
            SessionError::Io(e) => write!(f, "io error: {e}"),
            SessionError::Json(e) => write!(f, "json error: {e}"),
            SessionError::LogLine { line, message } => {
                write!(f, "log line {line}: {message}")
            }
        }
    }
}

impl std::error::Error for SessionError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            SessionError::Io(e) => Some(e),
            SessionError::Json(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for SessionError {
    fn from(e: io::Error) -> Self {
        SessionError::Io(e)
    }
}

impl From<serde_json::Error> for SessionError {
    fn from(e: serde_json::Error) -> Self {
        SessionError::Json(e)
    }
}

impl From<AgentError> for SessionError {
    fn from(e: AgentError) -> Self {
        SessionError::Io(io::Error::other(e.to_string()))
    }
}

/// Manages the set of active sessions within a working directory.
#[derive(Debug)]
pub struct SessionManager {
    working_dir: PathBuf,
    sessions: HashMap<String, Session>,
}

impl SessionManager {
    /// Create a new manager. `working_dir` is resolved relative to the
    /// process cwd at startup (the caller must resolve it).
    pub fn new(working_dir: impl Into<PathBuf>) -> Self {
        Self {
            working_dir: working_dir.into(),
            sessions: HashMap::new(),
        }
    }

    /// Path to the sessions directory: `<working_dir>/sessions/`.
    pub fn sessions_dir(&self) -> PathBuf {
        self.working_dir.join("sessions")
    }

    /// Check whether a session exists (by name) on disk.
    pub fn exists(&self, name: &str) -> bool {
        self.session_dir(name).exists()
    }

    /// List session names found on disk.
    pub fn list(&self) -> io::Result<Vec<String>> {
        let dir = self.sessions_dir();
        if !dir.exists() {
            return Ok(Vec::new());
        }
        let mut names = Vec::new();
        for entry in fs::read_dir(&dir)? {
            let entry = entry?;
            if entry.file_type()?.is_dir()
                && let Some(name) = entry.file_name().to_str()
            {
                names.push(name.to_string());
            }
        }
        names.sort();
        Ok(names)
    }

    /// Create a new session. Fails if the name is reserved or already exists.
    pub fn create(
        &mut self,
        name: &str,
        model: &str,
        system_prompt: &str,
    ) -> Result<&mut Session, SessionError> {
        if name == "default-session" {
            return Err(SessionError::ReservedName(name.into()));
        }
        if self.exists(name) {
            return Err(SessionError::AlreadyExists(name.into()));
        }
        let session = Session::create(&self.sessions_dir(), name, model, system_prompt)?;
        self.sessions.insert(name.to_string(), session);
        Ok(self.sessions.get_mut(name).expect("just inserted"))
    }

    /// Create the reserved auto session (`default-session`).
    ///
    /// Only the CLI's implicit auto-create path may call this; `create`
    /// rejects reserved names so users cannot claim them explicitly.
    pub fn create_default(
        &mut self,
        model: &str,
        system_prompt: &str,
    ) -> Result<&mut Session, SessionError> {
        if self.exists("default-session") {
            return Err(SessionError::AlreadyExists("default-session".into()));
        }
        let session = Session::create(
            &self.sessions_dir(),
            "default-session",
            model,
            system_prompt,
        )?;
        self.sessions.insert("default-session".to_string(), session);
        Ok(self
            .sessions
            .get_mut("default-session")
            .expect("just inserted"))
    }

    /// Open an existing session. Fails if it doesn't exist or is locked.
    pub fn open(&mut self, name: &str) -> Result<&mut Session, SessionError> {
        if self.sessions.contains_key(name) {
            return self
                .sessions
                .get_mut(name)
                .ok_or_else(|| SessionError::NotFound(name.into()));
        }
        if !self.exists(name) {
            return Err(SessionError::NotFound(name.into()));
        }
        let session = Session::open(&self.sessions_dir(), name)?;
        self.sessions.insert(name.to_string(), session);
        Ok(self.sessions.get_mut(name).expect("just inserted"))
    }

    /// Close a session: writes `session_closed`, flushes the log, and
    /// releases the filesystem lock.
    pub fn close(&mut self, name: &str) -> Result<(), SessionError> {
        let mut session = self
            .sessions
            .remove(name)
            .ok_or_else(|| SessionError::NotFound(name.into()))?;
        let turn = session.turn;
        session.log_entry(&LogEntry::session_closed(
            Utc::now(),
            turn,
            session.id.to_string(),
            session.name.clone(),
        ))?;
        drop(session); // releases lock
        Ok(())
    }

    /// Path to a specific session directory.
    fn session_dir(&self, name: &str) -> PathBuf {
        self.sessions_dir().join(name)
    }
}

/// A named, persistent session that holds on-disk state and a log writer.
///
/// Created and managed via [`SessionManager`]; not constructed directly.
/// Call [`Session::run`] with an agent to execute a turn with full logging.
#[derive(Debug)]
pub struct Session {
    /// Unique identifier for this session (stable across restarts).
    pub id: Uuid,
    /// Human-readable session name.
    pub name: String,
    /// When the session was first created.
    pub created_at: chrono::DateTime<Utc>,
    /// Model name in use.
    pub model: String,
    /// Current turn number (monotonically increasing).
    pub turn: u64,

    /// Path to the session directory on disk.
    root: PathBuf,
    /// Append-only event log writer.
    log: LogWriter,
    /// Filesystem lock held for the lifetime of this session.
    _guard: SessionGuard,
}

impl Session {
    /// Path to the session directory on disk.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Create a new session on disk. Internal — use `SessionManager::create`.
    fn create(
        sessions_dir: &Path,
        name: &str,
        model: &str,
        system_prompt: &str,
    ) -> Result<Self, SessionError> {
        let dir = sessions_dir.join(name);
        fs::create_dir_all(&dir)?;

        let guard = SessionGuard::acquire(&dir).map_err(|_| SessionError::Locked(name.into()))?;

        let id = Uuid::new_v4();
        let created_at = Utc::now();

        // Write session.json.
        let meta = serde_json::json!({
            "id": id.to_string(),
            "name": name,
            "created_at": created_at.to_rfc3339(),
            "model": model,
            "system_prompt": system_prompt,
        });
        fs::write(
            dir.join("session.json"),
            serde_json::to_string_pretty(&meta)?,
        )?;

        // Open the event log.
        let log_path = dir.join("events.jsonl");
        let mut log = LogWriter::open(&log_path)?;

        // Log creation and first open.
        let now = Utc::now();
        log.write_entry(&LogEntry::session_created(
            now,
            0,
            id.to_string(),
            name.to_string(),
            model.to_string(),
            system_prompt.to_string(),
        ))?;
        log.write_entry(&LogEntry::session_opened(
            now,
            0,
            id.to_string(),
            name.to_string(),
        ))?;

        Ok(Self {
            id,
            name: name.to_string(),
            created_at,
            model: model.to_string(),
            turn: 0,
            root: dir,
            log,
            _guard: guard,
        })
    }

    /// Open an existing session. Internal — use `SessionManager::open`.
    fn open(sessions_dir: &Path, name: &str) -> Result<Self, SessionError> {
        let dir = sessions_dir.join(name);
        if !dir.exists() {
            return Err(SessionError::NotFound(name.into()));
        }

        let guard = SessionGuard::acquire(&dir).map_err(|_| SessionError::Locked(name.into()))?;

        // Read session.json.
        let meta_path = dir.join("session.json");
        let meta_bytes = fs::read(&meta_path)?;
        let meta: serde_json::Value = serde_json::from_slice(&meta_bytes)?;
        let id: Uuid = meta["id"]
            .as_str()
            .and_then(|s| s.parse().ok())
            .unwrap_or_else(Uuid::new_v4);
        let created_at: chrono::DateTime<Utc> = meta["created_at"]
            .as_str()
            .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
            .map(|dt| dt.with_timezone(&Utc))
            .unwrap_or_else(Utc::now);
        let model = meta["model"].as_str().unwrap_or("unknown").to_string();

        let log_path = dir.join("events.jsonl");
        let mut log = LogWriter::open(&log_path)?;

        let now = Utc::now();
        log.write_entry(&LogEntry::session_opened(
            now,
            0,
            id.to_string(),
            name.to_string(),
        ))?;

        Ok(Self {
            id,
            name: name.to_string(),
            created_at,
            model,
            turn: 0,
            root: dir,
            log,
            _guard: guard,
        })
    }

    /// Run one user turn with full logging.
    ///
    /// Wraps the agent loop: for each model call and tool execution, an
    /// event is written to the session log. Returns the same `TurnSummary`
    /// as [`Agent::run`].
    pub async fn run<M: CompletionModel>(
        &mut self,
        agent: &mut Agent<M>,
        provider: &str,
        model_name: &str,
        user_input: &str,
    ) -> Result<TurnSummary, AgentError> {
        self.turn += 1;

        // Log user input.
        self.log_entry(&LogEntry::user_input(
            Utc::now(),
            self.turn,
            user_input.to_string(),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;

        let mut turn_messages: Vec<Message> = Vec::new();
        let mut tool_calls_total = 0usize;
        let mut usage_total = rig::completion::Usage::new();

        for _ in 0..agent.max_turns() {
            // Build and log the prompt.
            let tools = agent.tool_definitions();
            let messages_json = messages_for_log(
                agent.system_prompt(),
                agent.history(),
                &turn_messages,
                user_input,
            )?;
            let tools_json =
                serde_json::to_value(&tools).map_err(|e| AgentError::Rig(e.to_string()))?;
            self.log_entry(&LogEntry::llm_prompt(
                Utc::now(),
                self.turn,
                provider.to_string(),
                model_name.to_string(),
                messages_json,
                tools_json,
            ))
            .map_err(|e| AgentError::Rig(e.to_string()))?;

            // Call the model.
            let response = agent.single_completion(user_input, &turn_messages).await?;
            usage_total += response.usage;

            // Extract content from the response.
            let mut text_parts: Vec<rig::completion::message::Text> = Vec::new();
            let mut reasoning_parts: Vec<String> = Vec::new();
            let mut tool_calls: Vec<ToolCall> = Vec::new();
            for content in response.choice.iter() {
                match content {
                    AssistantContent::Text(t) => text_parts.push(t.clone()),
                    AssistantContent::ToolCall(call) => tool_calls.push(call.clone()),
                    AssistantContent::Reasoning(r) => {
                        reasoning_parts.push(r.display_text());
                    }
                    AssistantContent::Image(_) => {}
                }
            }

            // Log the response.
            let response_text = if text_parts.is_empty() {
                None
            } else {
                Some(
                    text_parts
                        .iter()
                        .map(|t| t.text())
                        .collect::<Vec<_>>()
                        .join("\n"),
                )
            };
            let response_reasoning = if reasoning_parts.is_empty() {
                None
            } else {
                Some(reasoning_parts.join("\n"))
            };
            let response_tool_calls: Option<Vec<ToolCallData>> = if tool_calls.is_empty() {
                None
            } else {
                Some(
                    tool_calls
                        .iter()
                        .map(|c| ToolCallData {
                            id: c.id.clone(),
                            name: c.function.name.clone(),
                            arguments: c.function.arguments.clone(),
                        })
                        .collect(),
                )
            };
            self.log_entry(&LogEntry::llm_response(
                Utc::now(),
                self.turn,
                response.message_id.clone(),
                response_text.clone(),
                response_reasoning,
                response_tool_calls.clone(),
                UsageData {
                    input_tokens: response.usage.input_tokens as u32,
                    output_tokens: response.usage.output_tokens as u32,
                },
            ))
            .map_err(|e| AgentError::Rig(e.to_string()))?;

            // No tool calls: turn complete.
            if tool_calls.is_empty() {
                let text = response_text.unwrap_or_default();
                turn_messages.push(Message::assistant(text.clone()));
                agent.commit_turn(user_input, turn_messages);

                self.log_entry(&LogEntry::turn_complete(
                    Utc::now(),
                    self.turn,
                    text.clone(),
                    tool_calls_total,
                ))
                .map_err(|e| AgentError::Rig(e.to_string()))?;

                return Ok(TurnSummary {
                    text,
                    tool_calls: tool_calls_total,
                    usage: usage_total,
                    final_history: agent.history().to_vec(),
                });
            }

            // Record the assistant message and execute tools.
            let mut contents: Vec<AssistantContent> =
                text_parts.into_iter().map(AssistantContent::Text).collect();
            contents.extend(tool_calls.iter().cloned().map(AssistantContent::ToolCall));
            turn_messages.push(Message::Assistant {
                id: response.message_id,
                content: rig::OneOrMany::from_iter_optional(contents)
                    .expect("assistant message has at least one tool call"),
            });

            for call in &tool_calls {
                let tool_args = call.function.arguments.clone();
                match agent.execute_tool(call).await {
                    Ok(output) => {
                        tool_calls_total += 1;
                        self.log_entry(&LogEntry::tool_execution(
                            Utc::now(),
                            self.turn,
                            call.id.clone(),
                            call.call_id.clone().unwrap_or_else(|| call.id.clone()),
                            call.function.name.clone(),
                            tool_args,
                            output.clone(),
                        ))
                        .map_err(|e| AgentError::Rig(e.to_string()))?;
                        turn_messages.push(Message::tool_result_with_call_id(
                            call.id.clone(),
                            call.call_id.clone(),
                            output,
                        ));
                    }
                    Err(e) => {
                        // Log error and bail.
                        self.log_entry(&LogEntry::error(
                            Utc::now(),
                            self.turn,
                            ErrorStage::ToolExecution,
                            e.to_string(),
                        ))
                        .map_err(|se| AgentError::Rig(se.to_string()))?;
                        agent.commit_turn(user_input, turn_messages);
                        return Err(e);
                    }
                }
            }
        }

        // Max turns exceeded.
        self.log_entry(&LogEntry::error(
            Utc::now(),
            self.turn,
            ErrorStage::LlmCall,
            format!("exceeded maximum of {} model turns", agent.max_turns()),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;
        agent.commit_turn(user_input, turn_messages);
        Err(AgentError::MaxTurns {
            turns: agent.max_turns(),
        })
    }

    /// Run one user turn with streaming output and full logging.
    ///
    /// Like [`run`], but model output arrives token-by-token through a
    /// channel. The caller reads [`StreamEvent`]s while the agent loop
    /// runs concurrently. Prompt, response, tool execution, completion,
    /// and error events are logged from the stream.
    ///
    /// [`StreamEvent`]: crate::agent::StreamEvent
    pub async fn run_streaming<M: CompletionModel + 'static>(
        &mut self,
        agent: &mut Agent<M>,
        provider: &str,
        model_name: &str,
        user_input: &str,
    ) -> Result<mpsc::Receiver<StreamEvent>, AgentError>
    where
        M::StreamingResponse: Send,
    {
        self.turn += 1;

        // Log user input.
        self.log_entry(&LogEntry::user_input(
            Utc::now(),
            self.turn,
            user_input.to_string(),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;

        let mut agent_rx = agent
            .run_streaming(user_input)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        let (tx, rx) = mpsc::channel(32);

        // Spawn a task that reads from the agent stream, writes log entries
        // for prompt/response/tool execution/completion/error, and forwards
        // events to the session's own channel.
        let turn = self.turn;
        let log_path = self.events_path();
        let provider = provider.to_string();
        let model_name = model_name.to_string();

        tokio::spawn(async move {
            let mut log_writer = match LogWriter::open(&log_path) {
                Ok(writer) => writer,
                Err(e) => {
                    let _ = tx
                        .send(StreamEvent::Error {
                            message: format!("re-open session log for streaming: {e}"),
                        })
                        .await;
                    return;
                }
            };

            let mut tool_calls_total: usize = 0;

            // Track tool arguments captured at ToolCallReady so the
            // tool_execution entry can log the real values (not a
            // placeholder).
            let mut pending_args: HashMap<String, serde_json::Value> = HashMap::new();

            while let Some(event) = agent_rx.recv().await {
                // Translate agent stream events into log entries. On writer
                // failure, report an error and stop logging further events.
                let write_result = match &event {
                    StreamEvent::ToolCallReady {
                        id,
                        name: _,
                        arguments,
                    } => {
                        pending_args.insert(id.clone(), arguments.clone());
                        Ok(())
                    }
                    StreamEvent::CompletionRequest {
                        ts,
                        messages,
                        tool_definitions,
                    } => log_writer.write_entry(&LogEntry::llm_prompt(
                        *ts,
                        turn,
                        provider.clone(),
                        model_name.clone(),
                        messages.clone(),
                        tool_definitions.clone(),
                    )),
                    StreamEvent::CompletionResponse {
                        ts,
                        message_id,
                        text,
                        reasoning,
                        tool_calls,
                        input_tokens,
                        output_tokens,
                    } => log_writer.write_entry(&LogEntry::llm_response(
                        *ts,
                        turn,
                        message_id.clone(),
                        text.clone(),
                        reasoning.clone(),
                        tool_calls.as_ref().map(|calls| {
                            calls
                                .iter()
                                .map(|c| ToolCallData {
                                    id: c.id.clone(),
                                    name: c.name.clone(),
                                    arguments: c.arguments.clone(),
                                })
                                .collect()
                        }),
                        UsageData {
                            input_tokens: *input_tokens as u32,
                            output_tokens: *output_tokens as u32,
                        },
                    )),
                    StreamEvent::ToolResult {
                        id,
                        name,
                        result,
                        result_preview: _,
                    } => {
                        tool_calls_total += 1;
                        let args = pending_args.remove(id).unwrap_or(serde_json::Value::Null);
                        // Log the real arguments and full result.
                        log_writer.write_entry(&LogEntry::tool_execution(
                            Utc::now(),
                            turn,
                            id.clone(),
                            id.clone(), // call_id same as tool_call_id (simplified)
                            name.clone(),
                            args,
                            result.clone(),
                        ))
                    }
                    StreamEvent::TurnComplete { summary } => {
                        log_writer.write_entry(&LogEntry::turn_complete(
                            Utc::now(),
                            turn,
                            summary.text.clone(),
                            tool_calls_total,
                        ))
                    }
                    StreamEvent::Error { message } => log_writer.write_entry(&LogEntry::error(
                        Utc::now(),
                        turn,
                        ErrorStage::LlmCall,
                        message.clone(),
                    )),
                    StreamEvent::TextDelta { .. }
                    | StreamEvent::ToolCallStart { .. }
                    | StreamEvent::ToolCallArgs { .. } => Ok(()),
                };

                if let Err(e) = write_result {
                    let _ = tx
                        .send(StreamEvent::Error {
                            message: format!("writing session log: {e}"),
                        })
                        .await;
                    let _ = tx.send(event).await;
                    break;
                }

                let _ = tx.send(event).await;
            }
        });

        Ok(rx)
    }

    /// Append an entry to the event log.
    pub fn log_entry(&mut self, entry: &LogEntry) -> Result<(), SessionError> {
        self.log.write_entry(entry)?;
        Ok(())
    }

    /// Read the full session metadata from `session.json`.
    pub fn read_meta(&self) -> Result<serde_json::Value, SessionError> {
        let meta_path = self.root.join("session.json");
        let bytes = fs::read(&meta_path)?;
        let value: serde_json::Value = serde_json::from_slice(&bytes)?;
        Ok(value)
    }

    /// Path to the events log file.
    pub fn events_path(&self) -> PathBuf {
        self.root.join("events.jsonl")
    }

    /// Path to the session metadata file.
    pub fn meta_path(&self) -> PathBuf {
        self.root.join("session.json")
    }

    /// Reconstruct agent message history from the event log.
    ///
    /// Walks the log, builds `Message` values for each completed turn, and
    /// stops at the last `turn_complete` or `error` boundary. Partial turns
    /// (events after the last complete turn without a close) are dropped.
    ///
    /// Tool calls and their results are paired by `tool_call_id`, not by
    /// log position, so both logging orders replay identically:
    ///
    /// - non-streaming: `llm_response` (tool calls) → `tool_execution`*
    /// - streaming:      `tool_execution`* → `llm_response` (tool calls)
    ///
    /// Lifecycle events (`session_created`, `session_opened`, etc.) and
    /// `llm_prompt` entries are skipped — they're not needed for history
    /// reconstruction.
    pub fn replay_history(&self) -> Result<Vec<Message>, SessionError> {
        let entries = self.events()?;
        let mut messages: Vec<Message> = Vec::new();
        let mut safe_len: usize = 0;
        let mut turn = TurnState::default();

        for entry in &entries {
            match entry {
                LogEntry::UserInput { data, .. } => {
                    // A new user message starts a fresh turn; any partial
                    // previous turn is dropped.
                    turn = TurnState::default();
                    turn.user = Some(data.text.clone());
                }
                LogEntry::LlmResponse { data, .. } => {
                    turn.responses.push(data.clone());
                }
                LogEntry::ToolExecution { data, .. } => {
                    turn.executions.push(data.clone());
                }
                LogEntry::TurnComplete { .. } | LogEntry::Error { .. } => {
                    // End of a completed turn — mark its messages as safe.
                    messages.extend(turn.replay());
                    safe_len = messages.len();
                    turn = TurnState::default();
                }
                // Skip lifecycle and prompt entries.
                LogEntry::SessionCreated { .. }
                | LogEntry::SessionOpened { .. }
                | LogEntry::SessionClosed { .. }
                | LogEntry::LlmPrompt { .. } => {}
            }
        }

        // Truncate to the last complete turn boundary.
        messages.truncate(safe_len);
        Ok(messages)
    }

    // --- Derived property accessors (Step 4) ---

    /// Parse all events from the log file and return them.
    pub fn events(&self) -> Result<Vec<LogEntry>, SessionError> {
        let path = self.events_path();
        if !path.exists() {
            return Ok(Vec::new());
        }
        let contents = fs::read_to_string(&path)?;
        self::log::parse_log_strict(&contents).map_err(|e| SessionError::LogLine {
            line: e.line,
            message: e.message,
        })
    }

    /// Compute cumulative token usage from all `llm_response` events.
    pub fn cumulative_usage(&self) -> Result<(u64, u64), SessionError> {
        let mut total_in: u64 = 0;
        let mut total_out: u64 = 0;
        for entry in self.events()? {
            if let LogEntry::LlmResponse { data, .. } = &entry {
                total_in += data.usage.input_tokens as u64;
                total_out += data.usage.output_tokens as u64;
            }
        }
        Ok((total_in, total_out))
    }

    /// Timestamp of the most recent `session_opened` event.
    pub fn last_opened_at(&self) -> Result<Option<chrono::DateTime<Utc>>, SessionError> {
        let events = self.events()?;
        let last = events
            .iter()
            .rev()
            .find(|e| matches!(e, LogEntry::SessionOpened { .. }));
        Ok(last.map(|e| e.ts()))
    }

    /// Total turns from the most recent `turn_complete` event.
    pub fn total_turns(&self) -> Result<u64, SessionError> {
        let events = self.events()?;
        let last = events
            .iter()
            .rev()
            .find(|e| matches!(e, LogEntry::TurnComplete { .. }));
        Ok(last.map(|e| e.turn()).unwrap_or(0))
    }

    /// Per-call model latencies computed from prompt/response timestamp
    /// pairs. Returns a vector of (ts, latency_ms) for each completed call.
    pub fn latencies(&self) -> Result<Vec<(chrono::DateTime<Utc>, i64)>, SessionError> {
        let events = self.events()?;
        let mut latencies = Vec::new();
        let mut pending_prompt_ts: Option<chrono::DateTime<Utc>> = None;

        for entry in &events {
            match entry {
                LogEntry::LlmPrompt { ts, .. } => {
                    pending_prompt_ts = Some(*ts);
                }
                LogEntry::LlmResponse { ts, .. } => {
                    if let Some(prompt_ts) = pending_prompt_ts.take() {
                        let latency_ms = (*ts - prompt_ts).num_milliseconds();
                        latencies.push((*ts, latency_ms));
                    }
                }
                _ => {}
            }
        }

        Ok(latencies)
    }
}

/// Events of one turn, in log order, awaiting reconstruction.
#[derive(Default)]
struct TurnState {
    user: Option<String>,
    responses: Vec<LlmResponseData>,
    executions: Vec<ToolExecutionData>,
}

impl TurnState {
    /// Rebuild the canonical OpenAI transcript for this turn.
    fn replay(&self) -> Vec<Message> {
        let mut out = Vec::new();
        if let Some(user) = &self.user {
            out.push(Message::user(user.clone()));
        }

        // Pair each declared tool call with its execution by id, not by
        // position, so streaming and non-streaming logs replay the same.
        let mut used = vec![false; self.executions.len()];

        for response in &self.responses {
            if let Some(tool_calls) = &response.tool_calls {
                let contents: Vec<AssistantContent> = tool_calls
                    .iter()
                    .map(|tc| {
                        AssistantContent::ToolCall(ToolCall::new(
                            tc.id.clone(),
                            ToolFunction {
                                name: tc.name.clone(),
                                arguments: tc.arguments.clone(),
                            },
                        ))
                    })
                    .collect();
                out.push(Message::Assistant {
                    id: response.message_id.clone(),
                    content: rig::OneOrMany::from_iter_optional(contents)
                        .expect("assistant message has at least one tool call"),
                });

                for tc in tool_calls {
                    let found = self
                        .executions
                        .iter()
                        .enumerate()
                        .find(|(i, e)| !used[*i] && e.tool_call_id == tc.id);

                    match found {
                        Some((idx, exec)) => {
                            used[idx] = true;
                            out.push(replay_tool_result(exec));
                        }
                        None => out.push(replay_error_tool_result(&tc.id)),
                    }
                }
            } else if let Some(text) = &response.text {
                out.push(Message::assistant(text.clone()));
            }
        }

        // Legacy streaming logs lack llm_response entries entirely, so any
        // unclaimed execution gets a synthetic assistant message.
        for (idx, exec) in self.executions.iter().enumerate() {
            if used[idx] {
                continue;
            }
            let tc = ToolCall::new(
                exec.tool_call_id.clone(),
                ToolFunction {
                    name: exec.name.clone(),
                    arguments: exec.arguments.clone(),
                },
            );
            out.push(Message::Assistant {
                id: None,
                content: rig::OneOrMany::one(AssistantContent::ToolCall(tc)),
            });
            out.push(replay_tool_result(exec));
        }

        out
    }
}

/// Render one logged tool execution as a tool-result message.
fn replay_tool_result(data: &ToolExecutionData) -> Message {
    let call_id = if data.call_id.is_empty() {
        data.tool_call_id.clone()
    } else {
        data.call_id.clone()
    };
    Message::tool_result_with_call_id(
        data.tool_call_id.clone(),
        Some(call_id),
        data.result.clone(),
    )
}

/// A declared tool call with no logged result must still be answered,
/// otherwise the transcript is 400-bound.
fn replay_error_tool_result(id: &str) -> Message {
    Message::tool_result_with_call_id(
        id.to_string(),
        Some(id.to_string()),
        format!("{{\"error\":\"no tool result recorded for call {id}\"}}"),
    )
}

